input.sparql:
SELECT ?p ?ts ?class WHERE {
  ?p a brick:CondenserPump .
  ?p rdfs:label ?p .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  OPTIONAL { ?p ?class ?x }
}

SELECT ?p ?ts WHERE {
  ?p ref:hasExternalReference ?r .
  ?p ref:hasTimeseriesId ?ts .
  FILTER(str(?p) LIKE "CondPump02%" || str(?p) LIKE "%CondPump02%")
}

SELECT ?p ?ts ?pc WHERE {
  ?p ref:hasTimeseriesId ?ts .
  ?p a ?pc .
  FILTER(str(?p) LIKE "%CondPump02%" || str(?p) LIKE "%condpump02%")
}

SELECT ?p ?pc ?ts WHERE {
  ?p a ?pc .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  FILTER(str(?pc) LIKE "%ump%" || str(?p) LIKE "%ump%" || str(?p) LIKE "%ond%")
}
